insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-pdf-refused-method-s646','decision','The PDF reader files a refused block under its own method, refused','The S646 conductor, decision 16(a), #3201 (merged e1f52690): a block the PDF reader refuses is filed with method refused, no text and no coverage, and listed in refused_passing. Round 4 found a refused block filed as an empty read page, so file_run dropped the old record. Final proof run 43381048821: 204 bound, 12 refused, 7 refused_passing.',array['program-requirements','decision'],'proposed','S646, PR 3201, run 43381048821',null,null,'SkyOriole (S646)',date '2026-11-13'),
('d-pdf-own-heading-exact-s646','decision','A block''s own heading is the full title with the same award, never a token subset','The S646 conductor, decision 17, #3201: an own heading is the program''s full title with the same award by normalized equality (AA is not AS); a wrapped heading of two or three lines, end-of-line hyphens rejoined, counts. Round 4 found a token subset read Art History, AA as Art, AA. 26 of 26 long-title refusals recovered. Minor follow-ups: Commercial Music, Pre-Engineering, Spanish AAT.',array['program-requirements','decision'],'proposed','S646, PR 3201, run 43381048821',null,null,'SkyOriole (S646)',date '2026-11-13'),
('p-filing-step-keep-all-refuted-s646','pitfall','A guard at a step every college shares changes every college','S646, decision 16(b) reversed by 18: the conductor had file_run keep any filed record a bound read did not replace, for every college. The second reader showed it kept a dropped program''s stale record, blocked a reread''s correction and a force. Removed: file_run describes one read; extract''s carry-forward protects the PDF route. Gate it, or read why the pinned test exists.',array['program-requirements','pitfall'],'proposed','S646, PR 3201, round 4 second reader',null,null,'SkyOriole (S646)',date '2026-11-13'),
('d-glendale-challenge-is-a-refusal-s646','decision','Glendale: a bot-check page is a refusal, read slowly, and a compare gate before any load','The S646 conductor, #3202: a bot-check page is answer kind challenge, a refusal never passed; route=challenged rereads refused codes, route=slow the catalog, at 12 s, each stopping at the first challenge; a GE pattern page fits only its own program; two Active programs never share a page on a title tie; extract carries a challenged program''s record forward; the compare tool runs before any load.',array['program-requirements','decision'],'proposed','S646, PR 3202, run 43379067418',null,null,'SkyOriole (S646)',date '2026-11-13'),
('p-route-untested-through-capture-s646','pitfall','A new capture route crashed in capture() because its tests called the reader directly','S646 (#3202): the first route=slow paid dispatch crashed before filing (UnboundLocalError, no cost) because the tests called _cd_read directly and never ran capture(). The reader caught it before the paid run cost anything. Tests now run capture() for every route. Brief the reader before dispatching a new route.',array['program-requirements','pitfall'],'proposed','S646, PR 3202',null,null,'SkyOriole (S646)',date '2026-11-13'),
('p-reread-cannot-feed-paid-read-s646','pitfall','A free reread cannot feed a paid read: no capture keeps page text','S646 (#3202): no capture keeps page text, so a free reread (extract=0) cannot feed a later extract=1 run; the paid read loads the pages again. Plan a paid read as its own capture.',array['program-requirements','pitfall'],'proposed','S646, PR 3202',null,null,'SkyOriole (S646)',date '2026-11-13'),
('google-agentic-architect-ga-2026-11-13','fact','Google''s Professional Agentic Architect is generally available','Credential watch 2026-11-13 (#3210, 8faf0960): Google''s own page shows the Professional Agentic Architect GA exam (2 hours, $200, 50 to 60 multiple-choice questions, one-year validity) with no beta label; the watch file moved it from beta to new. A tech giant launched an AI credential. It is not in MAP.',array['credential-registry','fact'],'proposed','PR 3210; kb/credential_watch_out/2026-11-13.md',null,null,'SkyOriole (S646)',date '2026-11-13')
